  on_linux do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.10/codesynapse-linux-arm64"
      sha256 "52b0c52cbc2fdd73a2cff5896c51f2b4dd0ffb42e249dc12b02dad9a2926a3a9"
